// blank*
func (p *parser) e5930() (*Node, bool) {
	count := 0
	for {
		m0 := p.mark()
		prevCut, prevFrame := p.cut, p.frame
		p.cut = false
		_, ok := p.e5929()
		cut := p.cut
		p.cut, p.frame = prevCut, prevFrame
		if !ok {
			p.reset(m0)
			if cut {
				return nil, false
			}
			break
		}
		count++
		if p.pos == m0.pos {
			break
		}
	}
	if count < 0 {
		return nil, false
	}
	return nil, true
}

